import{_ as o,o as r,c as s,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const _=JSON.parse('{"title":"关于本课程","description":"","frontmatter":{"title":"关于本课程"},"headers":[],"relativePath":"astock-course/about.md","filePath":"astock-course/docs/about.md"}'),n={name:"astock-course/about.md"};function i(l,t,e,g,c,p){return r(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="关于本课程" tabindex="-1">关于本课程 <a class="header-anchor" href="#关于本课程" aria-label="Permalink to &quot;关于本课程&quot;">​</a></h1><p>全书只回答一个问题：<strong>零基础的普通人进A股，凭什么长期赚钱，而不是给市场送钱？</strong></p><p>这门课写给手里有些积蓄、想进 A 股却不知道从哪下手的普通人。它不从 K 线口诀开始，也不推荐任何一只股票：先用三章把「钱、公司、规则」的地基打牢，再带你读懂行情语言（K 线与趋势），学会给公司称重（财报与估值），把风险与仓位算成可以落笔的数字，最后把全部积木装成一页纸投资体系与七步研究清单。每一章都有可核对的演算、可操作的验证和诚实的边界——技术分析能信几分、指数基金为什么是主力武器、为什么聪明人也亏钱，都给算术而不是给口号。</p><p>全课程共 16 章（16 章已完成）+ 3 个附录；输入为主题创作（零基础 A 股投资实战），无外部仓库依赖。演算验证物与图表数据由课程自带的 TypeScript 测试台固定种子生成，可复现、可核对。</p><h2 id="内容时效" tabindex="-1">内容时效 <a class="header-anchor" href="#内容时效" aria-label="Permalink to &quot;内容时效&quot;">​</a></h2><p>本课程内容截至 2026 年 9 月。交易规则、费率、税率、存款利率等时效性数字均在正文首现处标注生效日期与权威来源（如印花税 2023-08-28 起卖出单边万分之5；主板 ST 涨跌幅 2026-07-06 起统一为 10%），若已修订，以交易所与财政部等最新公告为准；存款利率锚会随挂牌调整，动手判定前先查最新。</p><h2 id="能力阶梯" tabindex="-1">能力阶梯 <a class="header-anchor" href="#能力阶梯" aria-label="Permalink to &quot;能力阶梯&quot;">​</a></h2><p>学完每一章，你会多一项能落笔的能力：</p><ul><li><strong>第 1 章</strong>：能算出任意本金/收益率/年限下的终值与实际购买力，判断一个收益率能否跑赢通胀</li><li><strong>第 2 章</strong>：能用股东视角说清股票收益的两个来源（企业盈利与估值变化），并解释为什么把股票当筹码追涨杀跌长期必输</li><li><strong>第 3 章</strong>：能算出一笔A股买卖的完整成本与涨跌停价格，判定任意下单时点的归属交易日与最早可卖时点</li><li><strong>第 4 章</strong>：能读出任意K线的开高低收与影线含义，结合成交量说出当日多空力量与典型形态</li><li><strong>第 5 章</strong>：能用均线判断趋势状态，并说出技术分析的适用边界与失效场景，不把它当预测水晶球</li><li><strong>第 6 章</strong>：能从简化三张表算出毛利率、净利率、经营现金流/净利润比等五项体检指标，识别利润与现金背离的危险信号</li><li><strong>第 7 章</strong>：能算任意公司的PE/PB/股息率，用无风险利率作锚判断当前价格贵不贵，建立「回本年限」直觉</li><li><strong>第 8 章</strong>：能用「价值-价格-安全边际」三要素判断一笔投资该不该出手，并用能力圈清单划定自己不碰的领域</li><li><strong>第 9 章</strong>：能算一笔持仓的最大回撤与回本所需涨幅，用「先定亏多少」的思路量化自己的风险承受力</li><li><strong>第 10 章</strong>：能用相关性解释为什么组合能降风险，给出一份股债基础配置并执行一次再平衡计算</li><li><strong>第 11 章</strong>：能按最大可承受亏损反推单一持仓与总仓位上限，制定并核算一份12期定投计划</li><li><strong>第 12 章</strong>：能识别损失厌恶、处置效应、锚定、从众四种陷阱在自己交易中的表现，并给每种配一条机械防御规则</li><li><strong>第 13 章</strong>：能说清指数与ETF的机制，算出费率的长期复利差与一份定投计划收益，用宽基指数搭建核心持仓</li><li><strong>第 14 章</strong>：能独立走完七步清单（生意→护城河→财报→估值→趋势→风险→决策），对一家真实上市公司产出可检查的买/不买结论</li><li><strong>第 15 章</strong>：能写出自己的一页纸投资计划书（目标、配置、买入规则、卖出规则、风控红线、复盘节奏），每条规则可检查、可执行</li><li><strong>第 16 章</strong>：能定位自己当前的能力缺口，选定一条12个月的进阶路径（行业分析/财报深研/估值进阶/工具化）</li></ul><p>全部能力在第 15 章装订成一页纸投资计划书，第 16 章给出从入门到专家的进阶地图。完整的词与公式在附录「术语表」与「速查表」。</p>',10)])])}const u=o(n,[["render",i]]);export{_ as __pageData,u as default};
